static Map<String,Map<String,Integer>> scores = Map.of(
    "Ant", Map.of("elastycznosc",9,"start",3,"szybkosc",5,"ekosystem",4,"przewidywalnosc",3),
    "Maven", Map.of("elastycznosc",4,"start",9,"szybkosc",6,"ekosystem",9,"przewidywalnosc",9),
    "Gradle", Map.of("elastycznosc",8,"start",6,"szybkosc",9,"ekosystem",7,"przewidywalnosc",6)
);
static double computeWeightedScore(String tool, Map<String,Double> weights) {
    var toolScores = scores.get(tool);
    double sum = 0, weightSum = 0;
    for (var e : weights.entrySet()) { sum += toolScores.get(e.getKey()) * e.getValue(); weightSum += e.getValue(); }
    return sum / weightSum;
}

static void analyzeComplexity(String content, String keyword) {
    long lines = content.lines().count();
    long keywordCount = content.lines().filter(l -> l.contains(keyword)).count();
    System.out.println("linii: " + lines + ", wystapien '" + keyword + "': " + keywordCount);
}
